/* @lc app=leetcode id=3336 lang=kotlin */ class Solution { fun g(a: Int, b: Int): Int = if (b == 0) a else g(b, a % b) fun subsequencePairCount(nums: IntArray): Int = 1_000_000_007L.let { M -> Array(201) { a -> IntArray(201) { b -> g(a, b) } }.let { gt -> nums.fold(Array(201) { LongArray(201) }.also { it[0][0] = 1L }) { dp, x -> Array(201) { dp[it].copyOf() }.also { nd -> (0..200).forEach { a -> (0..200).forEach { b -> if (dp[a][b] != 0L) gt[a][x].let { ga -> nd[ga][b] = (nd[ga][b] + dp[a][b]) % M }.also { gt[b][x].let { gb -> nd[a][gb] = (nd[a][gb] + dp[a][b]) % M } } } } } }.let { dp -> ((1..200).sumOf { dp[it][it] } % M).toInt() } } } }